+import java.nio.file.InvalidPathException;
 import java.nio.file.Path;
+import java.nio.file.StandardCopyOption;
 import java.util.zip.ZipEntry;
 import java.util.zip.ZipInputStream;

 public final class ZipUtils {

     private ZipUtils() {}

+    private static Path safeResolveZipEntry(Path destDir, String entryName) throws IOException {
+        // Zip entries always use '/' as separator, but attackers can use '\' to bypass checks on Unix.
+        String normalizedName = entryName.replace('\\', '/');
+
+        Path destAbs = destDir.toAbsolutePath().normalize();
+        final Path targetAbs;
+        try {
+            targetAbs = destAbs.resolve(normalizedName).normalize();
+        } catch (InvalidPathException e) {
+            throw new IOException("Invalid zip entry path: " + entryName, e);
+        }
+
+        if (!targetAbs.startsWith(destAbs)) {
+            throw new IOException("Blocked zip entry with illegal path: " + entryName);
+        }
+        return targetAbs;
+    }
+
     public static void unzip(InputStream is, Path dest) throws IOException {
         if (!Files.exists(dest)) {
             Files.createDirectories(dest);
         }

         try (ZipInputStream zis = new ZipInputStream(is)) {
             ZipEntry entry;
             while ((entry = zis.getNextEntry()) != null) {
-                Path filePath = dest.resolve(entry.getName());
-                if (entry.isDirectory()) {
-                    Files.createDirectories(filePath);
-                } else {
-                    Files.createDirectories(filePath.getParent());
-                    Files.copy(zis, filePath);
-                }
+                Path filePath = safeResolveZipEntry(dest, entry.getName());
+                if (entry.isDirectory()) {
+                    Files.createDirectories(filePath);
+                    zis.closeEntry();
+                    continue;
+                }
+
+                Path parent = filePath.getParent();
+                if (parent != null) {
+                    Files.createDirectories(parent);
+                }
+                Files.copy(zis, filePath, StandardCopyOption.REPLACE_EXISTING);
                 zis.closeEntry();
