+/**
+ * Sanitize a Strapi populate parameter against an allow-list.
+ *
+ * This function is intentionally defensive:
+ *  - If allow-list is missing/invalid => deny (return null).
+ *  - If requested populate contains disallowed paths => drop them.
+ *  - Wildcards ('*' / true) are expanded to the allow-list only.
+ *
+ * Supported populate forms (Strapi v4):
+ *  - '*' / true
+ *  - ['relationA', 'relationB']
+ *  - { relationA: true, relationB: { populate: ... } }
+ */
+function sanitizePopulate(requested, allowed) {
+  if (!allowed || typeof allowed !== 'object') {
+    // Without a reliable allow-list, do not allow population at all.
+    return null;
+  }
+
+  const allowedKeys = Object.keys(allowed);
+  if (allowedKeys.length === 0) return null;
+
+  // '*' / true means "populate everything" -> reduce to allow-list.
+  if (requested === '*' || requested === true) {
+    const out = {};
+    for (const k of allowedKeys) out[k] = allowed[k];
+    return out;
+  }
+
+  // Array form -> keep only allowed relations.
+  if (Array.isArray(requested)) {
+    const out = {};
+    for (const k of requested) {
+      if (typeof k !== 'string') continue;
+      if (Object.prototype.hasOwnProperty.call(allowed, k)) {
+        out[k] = allowed[k];
+      }
+    }
+    return Object.keys(out).length ? out : null;
+  }
+
+  // Object form -> recursively sanitize nested populate.
+  if (requested && typeof requested === 'object') {
+    const out = {};
+    for (const [key, value] of Object.entries(requested)) {
+      if (!Object.prototype.hasOwnProperty.call(allowed, key)) continue;
+
+      const allowedEntry = allowed[key];
+
+      // If allowedEntry is a boolean, allow the relation (and any nested populate
+      // requested) only when explicitly permitted.
+      if (allowedEntry === true) {
+        out[key] = value === undefined ? true : value;
+        continue;
+      }
+
+      // If allowedEntry is an object, only allow nested populate that is also allowed.
+      if (allowedEntry && typeof allowedEntry === 'object') {
+        // If requester doesn't ask for nested populate, allow the relation itself.
+        if (value === true || value == null) {
+          out[key] = true;
+          continue;
+        }
+
+        // If nested populate exists, sanitize it against the nested allow-list.
+        if (value && typeof value === 'object') {
+          const requestedNested = value.populate;
+          const allowedNested =
+            (allowedEntry && typeof allowedEntry === 'object' && allowedEntry.populate) ||
+            (allowedEntry && typeof allowedEntry === 'object' ? allowedEntry : null);
+
+          if (requestedNested === undefined) {
+            // No nested populate requested -> allow relation only.
+            out[key] = true;
+            continue;
+          }
+
+          const nested = sanitizePopulate(requestedNested, allowedNested);
+          if (nested == null) {
+            // No allowed nested populate -> still allow relation itself (not nested).
+            out[key] = true;
+          } else {
