+import Foundation
+
+/// Centralized decoding limits to prevent resource-exhaustion (CWE-400) when parsing untrusted WASM.
+///
+/// These limits are intentionally generous for typical WASM modules, but prevent pathological
+/// allocations/loops (e.g., huge vector/string lengths) that can lead to denial of service.
+enum WasmDecodingLimits {
+    /// Maximum allowed WASM module size (bytes).
+    static let maxModuleBytes: Int = 50 * 1024 * 1024 // 50 MiB
+
+    /// Maximum bytes allowed to be read in a single `readBytes(count:)` call.
+    /// Used to cap section/function-body reads.
+    static let maxReadBytes: Int = 25 * 1024 * 1024 // 25 MiB
+
+    /// Maximum number of elements in a WASM vector.
+    static let maxVectorCount: Int = 1_000_000
+
+    /// Maximum length (bytes) for a UTF-8 name/string in the binary format.
+    static let maxStringBytes: Int = 1 * 1024 * 1024 // 1 MiB
+}
+
+enum WasmDecodingError: Error {
+    case resourceLimitExceeded(String)
+}
